`timescale 1ns/1ps
module validation_vendor_masked_tb;
 reg wclk=0,wce=1,we=0,rclk=0,rce=1,re=0,reset_output=0;
 reg [3:0]wstrb=0;reg[8:0]waddr=0,raddr=0;reg[31:0]wdata=0;
 wire[31:0]rdata;
 nano_sdp32_masked dut(.*);
 reg[31:0]expected[0:511];reg[31:0]held;integer i,j,reads=0;
 task write_word(input integer a,input[31:0]data,input[3:0]mask);begin
  we=1;waddr=a;wdata=data;wstrb=mask;
  for(j=0;j<4;j=j+1)if(mask[j])expected[a][j*8+:8]=data[j*8+:8];
  #5;wclk=1;#5;wclk=0;we=0;
 end endtask
 task read_word(input integer a);begin
  raddr=a;re=1;#5;rclk=1;#5;rclk=0;re=0;
  if(rdata!==expected[a])$fatal(1,"native mask address%0d got%h expected%h",a,rdata,expected[a]);
  reads=reads+1;
 end endtask
 initial begin
  for(i=0;i<512;i=i+1)begin expected[i]=0;write_word(i,32'hcafebabe^i*32'h1f0e0d0c,4'hf);end
