   write_word(i,32'h01234567^i,4'h3);read_word(i);
   write_word(i,32'h89abcdef^i,4'hc);read_word(i);
   write_word(i,32'h10325476^i,4'h5);read_word(i);
   write_word(i,32'hfedcba98^i,4'ha);read_word(i);
   write_word(i,32'hffffffff,4'h0);read_word(i);
